        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_13(1, 1)::text;
        n := 2;
        t := pj_ops_f8_13(1, 1)::text;
        n := 3;
        t := pj_ops_f8_13(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_14(1, 1)::text;
        n := 2;
        t := pj_ops_f8_14(1, 1)::text;
        n := 3;
        t := pj_ops_f8_14(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_15(1, 1)::text;
        n := 2;
        t := pj_ops_f8_15(1, 1)::text;
        n := 3;
        t := pj_ops_f8_15(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_16(1, 1)::text;
        n := 2;
        t := pj_ops_f8_16(1, 1)::text;
        n := 3;
        t := pj_ops_f8_16(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_17(NULL, 1)::text;
        n := 2;
        t := pj_ops_f8_17(NULL, 1)::text;
        n := 3;
        t := pj_ops_f8_17(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_18(1, 1)::text;
        n := 2;
        t := pj_ops_f8_18(1, 1)::text;
        n := 3;
        t := pj_ops_f8_18(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_19(1, 1)::text;
        n := 2;
        t := pj_ops_f8_19(1, 1)::text;
        n := 3;
        t := pj_ops_f8_19(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_20(1, 1)::text;
        n := 2;
        t := pj_ops_f8_20(1, 1)::text;
        n := 3;
        t := pj_ops_f8_20(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_f8_21(1, 1)::text;
        n := 2;
        t := pj_ops_f8_21(1, 1)::text;
        n := 3;
        t := pj_ops_f8_21(v_float8[i], v_float8[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      INSERT INTO pj_ops_res (grp, x, y, r)
        VALUES ('f8', v_float8[i], v_float8[j], rtrim(r));
      COMMIT;
    END LOOP;
  END LOOP;
  FOR i IN 1..array_length(v_bool, 1) LOOP
    FOR j IN 1..array_length(v_bool, 1) LOOP
      r := '';
      BEGIN
        n := 1;
        t := pj_ops_bool_0(true, true)::text;
        n := 2;
        t := pj_ops_bool_0(true, true)::text;
        n := 3;
        t := pj_ops_bool_0(v_bool[i], v_bool[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_bool_1(true, true)::text;
        n := 2;
        t := pj_ops_bool_1(true, true)::text;
        n := 3;
        t := pj_ops_bool_1(v_bool[i], v_bool[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_bool_2(true, true)::text;
        n := 2;
        t := pj_ops_bool_2(true, true)::text;
        n := 3;
        t := pj_ops_bool_2(v_bool[i], v_bool[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      BEGIN
        n := 1;
        t := pj_ops_bool_3(true, true)::text;
        n := 2;
        t := pj_ops_bool_3(true, true)::text;
        n := 3;
        t := pj_ops_bool_3(v_bool[i], v_bool[j])::text;
        r := r || coalesce(t, 'N') || ' ';
      EXCEPTION WHEN OTHERS THEN
        r := r || CASE WHEN n < 3 THEN 'B' ELSE 'E' || SQLSTATE END || ' ';
      END;
      INSERT INTO pj_ops_res (grp, x, y, r)
        VALUES ('bool', v_bool[i], v_bool[j], rtrim(r));
      COMMIT;
    END LOOP;
  END LOOP;
END
$$;

CALL pj_ops_run();

-- with plpgsql_jit active, every case ran compiled
DO $$
DECLARE
  got text[];
BEGIN
  IF current_setting('plllvm.plpgsql_jit', true)::bool
     AND current_setting('debug_discard_caches')::int = 0 THEN
    EXECUTE 'SELECT coalesce(array_agg(p.proname ORDER BY p.proname), ''{}'')
               FROM pg_proc p, LATERAL plllvm_pj_status(p.oid::regprocedure) s
              WHERE p.proname LIKE ''pj\_ops\_%'' AND s.last_path <> ''compiled'''
      INTO got;
    IF got <> '{}' THEN
      RAISE EXCEPTION 'not compiled: %', got;
    END IF;
  END IF;
END
$$;

-- every case, one row per pair of values
\a
SELECT grp, coalesce(x, 'N') AS x, coalesce(y, 'N') AS y, r
  FROM pj_ops_res ORDER BY id;
\a

-- what the cases raised
SELECT grp, count(*) AS cases,
       count(*) FILTER (WHERE t = 'E22003') AS out_of_range,
       count(*) FILTER (WHERE t = 'E22012') AS division_by_zero,
       count(*) FILTER (WHERE t LIKE 'E%') AS errors,
       count(*) FILTER (WHERE t = 'N') AS nulls,
       count(*) FILTER (WHERE t = 'B') AS harmless_failed
  FROM pj_ops_res, regexp_split_to_table(r, ' ') t
 GROUP BY ROLLUP (grp) ORDER BY grp;

